from src.billing.tax import line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_returns_int_cents():
    assert tax_for(1000, Decimal("0.0825")) == 82
    assert isinstance(tax_for(1000, Decimal("0.0825")), int)


def test_tax_for_uses_bankers_rounding():
    # 50 * 0.05 = 2.5 -> 2 (half to even), 70 * 0.05 = 3.5 -> 4
    assert tax_for(50, Decimal("0.05")) == 2
    assert tax_for(70, Decimal("0.05")) == 4


def test_tax_for_accepts_float_rate_without_drift():
    # 0.0825 as a binary float is slightly below 0.0825; must still be exact.
    assert tax_for(200, 0.0825) == tax_for(200, Decimal("0.0825")) == 16
    assert tax_for(1000, 0.0825) == 82


def test_tax_for_zero():
    assert tax_for(0, Decimal("0.2")) == 0"
}

